/* ── 6. 大运相位（不得落到占位段）── */
console.log('\n【6】大运相位判定');
{
  // 注意：起运时间取决于出生到节气的距离，可以短到几个月。
  // 所以不能假设"幼儿一定未起运"—— 早先版本就因此写错过测试。
  // 改为检验不变量：phase 必须与 daYun 数据自洽。
  const years = [new Date().getFullYear() - 1, 1990, 1975, 1960, 1901];
  let invariantOk = true, badCase = '';
  years.forEach((y) => {
    const c = B.chart({ y, m: 5, d: 15, h: 14, mi: 30, gender: '男', lonEast: 116.4, lat: 39.9 });
    const cur = c.current;
    const okIn = cur.phase === 'in'
      ? (cur.daYunIndex >= 0 && cur.daYun && cur.daYun.isCurrent && cur.daYun.gz !== '—')
      : true;
    const okNotIn = cur.phase !== 'in' ? cur.daYunIndex === -1 && cur.daYun === null : true;
    if (!(okIn && okNotIn)) { invariantOk = false; badCase = y + ' phase=' + cur.phase + ' idx=' + cur.daYunIndex; }
  });
  t('phase 与 daYun 数据自洽（5 个年份）', invariantOk, badCase);

  const young = B.chart({ y: new Date().getFullYear(), m: 12, d: 31, h: 10, mi: 0, gender: '男', lonEast: 120, lat: 30 });
  t('当年出生 → 必为 before（起运最早也要几个月后）', young.current.phase === 'before', young.current.phase);

  const old = B.chart({ y: 1901, m: 3, d: 5, h: 8, mi: 0, gender: '男', lonEast: 120, lat: 30 });
  t('1901 年生 → phase=after（已走完）', old.current.phase === 'after', old.current.phase);

  const normal = B.chart({ y: 1990, m: 5, d: 15, h: 14, mi: 30, gender: '男', lonEast: 116.4, lat: 39.9 });
  t('1990 年生 → phase=in 且大运有干支', normal.current.phase === 'in' && normal.current.daYun.gz !== '—');
}

